/* Clinical Timeline stagger animation */
@keyframes slideInFade {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.timeline__rail {
  animation: slideInFade 0.6s var(--ease-out-strong) 0s forwards;
}

.timeline .group {
  animation: slideInFade 0.5s var(--ease-out-strong) backwards;
}

.timeline .group:nth-child(1) { animation-delay: 0.1s; }
.timeline .group:nth-child(2) { animation-delay: 0.2s; }
.timeline .group:nth-child(3) { animation-delay: 0.3s; }
.timeline .group:nth-child(4) { animation-delay: 0.4s; }
.timeline .group:nth-child(5) { animation-delay: 0.5s; }

.timeline .event:hover {
  background: var(--hover);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── Touch target minimum (44px WCAG) ── */
@media (hover: none) and (pointer: coarse) {
  .sidebar-row {
    min-height: 44px;
  }
  /* Grid card action buttons — always visible on touch */
  .primitive-card .absolute > button {
    min-width: 44px;
    min-height: 44px;
  }
  /* PromptBar controls — enlarge on touch */
  [data-promptbar] button[aria-label] {
    min-width: 44px;
    min-height: 44px;
  }
}

/* Hide sidebar controls on mobile (no sidebar to collapse) */
@media (max-width: 1023px) {
  .sidebar-collapse-control {
    display: none;
  }
  .sidebar-workspace-control {
    display: none;
  }
  .sidebar-header {
    display: none;
  }
}
